-- Operational evidence previously changed without a history event because the original order
-- trigger watches only status, total, provider environment, promo and carrier fields.
-- Notes, addresses, payment references and customer text remain only in their protected records.
-- withAuditDb supplies staff/system identity in the same transaction as the guarded order write.
CREATE TRIGGER IF NOT EXISTS audit_order_operations_update AFTER UPDATE ON orders
WHEN json_object('Payment verification',CASE WHEN json_type(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.paymentVerified.state')='text' AND length(json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.paymentVerified.state'))<=120 THEN json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.paymentVerified.state') ELSE NULL END,'Payment checked at',CASE WHEN json_type(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.paymentVerified.at') IN ('integer','real') THEN json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.paymentVerified.at') ELSE NULL END,'Preorder released at',CASE WHEN json_type(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.preorderRelease.at') IN ('integer','real') THEN json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.preorderRelease.at') ELSE NULL END,'Handoff recorded at',CASE WHEN json_type(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.handoff.at') IN ('integer','real') THEN json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.handoff.at') ELSE NULL END,'Hold issue',CASE WHEN json_type(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.hold.issue')='text' AND length(json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.hold.issue'))<=120 THEN json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.hold.issue') ELSE NULL END,'Archived at',CASE WHEN json_type(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.archivedAt') IN ('integer','real') THEN json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.archivedAt') ELSE NULL END) IS NOT json_object('Payment verification',CASE WHEN json_type(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.paymentVerified.state')='text' AND length(json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.paymentVerified.state'))<=120 THEN json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.paymentVerified.state') ELSE NULL END,'Payment checked at',CASE WHEN json_type(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.paymentVerified.at') IN ('integer','real') THEN json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.paymentVerified.at') ELSE NULL END,'Preorder released at',CASE WHEN json_type(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.preorderRelease.at') IN ('integer','real') THEN json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.preorderRelease.at') ELSE NULL END,'Handoff recorded at',CASE WHEN json_type(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.handoff.at') IN ('integer','real') THEN json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.handoff.at') ELSE NULL END,'Hold issue',CASE WHEN json_type(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.hold.issue')='text' AND length(json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.hold.issue'))<=120 THEN json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.hold.issue') ELSE NULL END,'Archived at',CASE WHEN json_type(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.archivedAt') IN ('integer','real') THEN json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.archivedAt') ELSE NULL END)
BEGIN
 INSERT INTO change_events(id,occurred_at,recorded_at,source,actor,actor_type,action,entity_type,entity_id,summary,status,changes)
 VALUES(lower(hex(randomblob(16))),CAST((julianday('now')-2440587.5)*86400000 AS INTEGER),CAST((julianday('now')-2440587.5)*86400000 AS INTEGER),
  COALESCE((SELECT source FROM change_context WHERE id=1),'system'),
  COALESCE((SELECT actor FROM change_context WHERE id=1),'Unattributed database change'),
  COALESCE((SELECT actor_type FROM change_context WHERE id=1),'unknown'),
  COALESCE((SELECT action FROM change_context WHERE id=1),'order.operations.update'),'order',CAST(NEW.id AS TEXT),
  COALESCE((SELECT summary FROM change_context WHERE id=1),'Order payment or fulfillment evidence updated'),'succeeded',
  (SELECT json_group_array(json_object('field',a.key,'before',a.value,'after',b.value)) FROM json_each(json_object('Payment verification',CASE WHEN json_type(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.paymentVerified.state')='text' AND length(json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.paymentVerified.state'))<=120 THEN json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.paymentVerified.state') ELSE NULL END,'Payment checked at',CASE WHEN json_type(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.paymentVerified.at') IN ('integer','real') THEN json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.paymentVerified.at') ELSE NULL END,'Preorder released at',CASE WHEN json_type(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.preorderRelease.at') IN ('integer','real') THEN json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.preorderRelease.at') ELSE NULL END,'Handoff recorded at',CASE WHEN json_type(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.handoff.at') IN ('integer','real') THEN json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.handoff.at') ELSE NULL END,'Hold issue',CASE WHEN json_type(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.hold.issue')='text' AND length(json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.hold.issue'))<=120 THEN json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.hold.issue') ELSE NULL END,'Archived at',CASE WHEN json_type(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.archivedAt') IN ('integer','real') THEN json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.archivedAt') ELSE NULL END)) a JOIN json_each(json_object('Payment verification',CASE WHEN json_type(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.paymentVerified.state')='text' AND length(json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.paymentVerified.state'))<=120 THEN json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.paymentVerified.state') ELSE NULL END,'Payment checked at',CASE WHEN json_type(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.paymentVerified.at') IN ('integer','real') THEN json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.paymentVerified.at') ELSE NULL END,'Preorder released at',CASE WHEN json_type(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.preorderRelease.at') IN ('integer','real') THEN json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.preorderRelease.at') ELSE NULL END,'Handoff recorded at',CASE WHEN json_type(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.handoff.at') IN ('integer','real') THEN json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.handoff.at') ELSE NULL END,'Hold issue',CASE WHEN json_type(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.hold.issue')='text' AND length(json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.hold.issue'))<=120 THEN json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.hold.issue') ELSE NULL END,'Archived at',CASE WHEN json_type(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.archivedAt') IN ('integer','real') THEN json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.archivedAt') ELSE NULL END)) b ON a.key=b.key WHERE a.value IS NOT b.value));
END;
